import React,{useEffect,useState} from 'react';
import {collectionsAPI} from '../services/api';
export default function CollectionsPage(){const[data,setData]=useState(null);useEffect(()=>{collectionsAPI.getOverview().then(r=>setData(r.data)).catch(console.error)},[]);if(!data)return <div className="container py-5">Chargement…</div>;return <div className="container collections-page"><section className="collections-hero"><span className="section-kicker">WELLCASE / COLLECTIONS</span><h1>Complète tes <em>collections.</em></h1><p>Posséder toutes les armes d’une catégorie débloque un avantage permanent et un badge de collectionneur.</p></section><div className="collections-grid">{data.collections.map(c=><article className={`collection-card ${c.complete?'complete':''}`} key={c.key}><div className="collection-icon">{c.key==='Knives'?'◈':c.key==='Gloves'?'◉':c.key==='Snipers'?'⌁':'✦'}</div><div><span>{c.label}</span><h2>{c.owned} / {c.total}</h2><div className="collection-track"><i style={{width:`${c.total?c.owned/c.total*100:0}%`}}/></div><p>{c.bonus}</p>{c.complete&&<strong>✓ {c.badge}</strong>}</div></article>)}</div></div>}
